SELECT (CAST(c.Year AS INTEGER) - 3) - (SELECT MIN(CAST(Year AS INTEGER)) FROM concert) AS years
FROM concert c
WHERE c.Theme = 'Wide Awake';

SELECT 100.0 * (
  SELECT COUNT(*)
  FROM concert
  WHERE
    (Theme != 'Bleeding Love' AND Stadium_ID IN (
      SELECT Stadium_ID FROM stadium ORDER BY Average DESC LIMIT 3
    ))
    OR
    (Theme = 'Bleeding Love' AND (
      SELECT Stadium_ID FROM stadium WHERE Name = 'Glebe Park'
    ) IN (
      SELECT Stadium_ID FROM stadium ORDER BY Average DESC LIMIT 3
    ))
) / (
  SELECT COUNT(*) FROM concert
) AS percentage;
